"use client"

import { revalidateLogic } from "@tanstack/react-form"
import type { ReactNode } from "react"
import { z } from "zod"

import { Button } from "@/components/ui/button"
import { FieldGroup } from "@/components/ui/field"
import { AuthLink } from "@/components/openlmis/auth-card"
import {
  FormDialog,
  FormDialogBody,
  FormDialogDescription,
  FormDialogError,
  FormDialogFooter,
  FormDialogForm,
  FormDialogHeader,
  FormDialogSubmit,
  FormDialogTitle,
} from "@/components/openlmis/form-dialog/form-dialog"
import { useDialogTarget } from "@/components/openlmis/form-dialog/use-dialog-target"
import { useAppForm } from "@/components/openlmis/form-fields/form"

// Its own field name, so its id never clashes with a password field on the page behind it.
const passwordSchema = z.object({
  sessionPassword: z.string().min(1, "Password is required."),
})

type SessionExpiredDialogProps = {
  /** Open while the session is expired; only signing in or out should close it. */
  open: boolean
  /** Who was signed in; only the password is asked for. */
  username: string
  onSignIn: (password: string) => void
  onSignOut: () => void
  /** Signing in. */
  pending?: boolean
  /** Signing out. */
  signingOut?: boolean
  /** Why signing in failed, e.g. a wrong password. */
  error?: ReactNode
  forgotPasswordHref?: string
  /** Where a close button would be, e.g. a language switcher. */
  action?: ReactNode
}

const keepOpen = () => {}

/** Over whatever page was open when the session ran out, until the same user signs in or out. */
export function SessionExpiredDialog({
  open,
  username,
  onSignIn,
  onSignOut,
  pending = false,
  signingOut = false,
  error,
  forgotPasswordHref = "/forgot-password",
  action,
}: SessionExpiredDialogProps) {
  // Keeps the last username through the close animation, so the dialog never empties as it fades.
  const { shown, dialogProps } = useDialogTarget(
    open ? username : undefined,
    keepOpen
  )

  return (
    // The pages behind are waiting on it, so there is no close button.
    <FormDialog closeButton={false} {...dialogProps()}>
      {shown && (
        <SignInAgainForm
          action={action}
          error={error}
          forgotPasswordHref={forgotPasswordHref}
          onSignIn={onSignIn}
          onSignOut={onSignOut}
          pending={pending}
          signingOut={signingOut}
          username={shown}
        />
      )}
    </FormDialog>
  )
}

function SignInAgainForm({
  username,
  onSignIn,
  onSignOut,
  pending,
  signingOut,
  error,
  forgotPasswordHref,
  action,
}: Omit<SessionExpiredDialogProps, "open" | "pending" | "signingOut"> & {
  pending: boolean
  signingOut: boolean
  forgotPasswordHref: string
}) {
  const form = useAppForm({
    defaultValues: { sessionPassword: "" },
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: passwordSchema },
    onSubmit: ({ value }) => onSignIn(value.sessionPassword),
  })

  return (
    <FormDialogForm onSubmit={form.handleSubmit}>
      {action && <div className="absolute end-2 top-2">{action}</div>}
      <FormDialogHeader>
        <FormDialogTitle>Session Expired</FormDialogTitle>
        <FormDialogDescription>
          You were signed out after a period of inactivity. Sign in again to
          carry on. Your unsaved changes are kept.
        </FormDialogDescription>
      </FormDialogHeader>
      <FormDialogBody>
        <FieldGroup>
          {error && (
            <FormDialogError description={error} title="Sign In Failed" />
          )}
          {/* Lets password managers offer the password saved for this account. */}
          <input autoComplete="username" hidden readOnly value={username} />
          <form.AppField name="sessionPassword">
            {(field) => (
              <field.PasswordField
                action={
                  // A new tab, so the page and its unsaved work stay behind the dialog.
                  <AuthLink href={forgotPasswordHref} newTab>
                    Forgot Password?
                  </AuthLink>
                }
                autoComplete="current-password"
                description={
                  <>
                    Signed in as{" "}
                    <span className="font-medium text-foreground">
                      {username}
                    </span>
                  </>
                }
                label="Password"
                placeholder="Enter Your Password"
              />
            )}
          </form.AppField>
        </FieldGroup>
      </FormDialogBody>
      <FormDialogFooter>
        <Button
          disabled={pending || signingOut}
          onClick={onSignOut}
          type="button"
          variant="destructive"
        >
          Sign Out
        </Button>
        <FormDialogSubmit disabled={signingOut} pending={pending}>
          {pending ? "Signing In..." : "Sign In"}
        </FormDialogSubmit>
      </FormDialogFooter>
    </FormDialogForm>
  )
}

"use client"

import { revalidateLogic } from "@tanstack/react-form"
import type { ReactNode } from "react"
import { z } from "zod"

import { CardContent, CardDescription } from "@/components/ui/card"
import { FormDialogError } from "@/components/openlmis/form-dialog/form-dialog"
import { useAppForm } from "@/components/openlmis/form-fields/form"

import {
  AuthForm,
  AuthHeader,
  AuthLink,
  AuthSubmit,
  AuthTitle,
} from "@/components/openlmis/auth-card"

export type SignInCredentials = { username: string; password: string }

const signInSchema = z.object({
  username: z
    .string()
    .min(1, "Username is required.")
    .max(255, "Username must be at most 255 characters."),
  password: z.string().min(1, "Password is required."),
})

type SignInFormProps = {
  /** Named in the description: "Enter your {appName} credentials". */
  appName?: string
  logo?: ReactNode
  forgotPasswordHref?: string
  onSubmit: (credentials: SignInCredentials) => void
  /** Shows a spinner on Sign In while the credentials are checked. */
  pending?: boolean
  /** Why sign-in was refused, shown above the fields. */
  error?: ReactNode
}

/** The sign-in card's content; render it inside `AuthPage`. */
export function SignInForm({
  appName = "OpenLMIS",
  logo,
  forgotPasswordHref = "/forgot-password",
  onSubmit,
  pending = false,
  error,
}: SignInFormProps) {
  const form = useAppForm({
    defaultValues: { username: "", password: "" },
    // Quiet until the first submit, then each field re-checks as it is corrected.
    validationLogic: revalidateLogic({
      mode: "submit",
      modeAfterSubmission: "change",
    }),
    validators: { onDynamic: signInSchema },
    onSubmit: ({ value }) => onSubmit(value),
  })

  return (
    <>
      <AuthHeader logo={logo}>
        <AuthTitle>Sign In</AuthTitle>
        <CardDescription>
          Enter your {appName} credentials to continue.
        </CardDescription>
      </AuthHeader>

      <CardContent>
        <AuthForm onSubmit={form.handleSubmit}>
          {error && (
            <FormDialogError description={error} title="Sign In Failed" />
          )}
          <form.AppField name="username">
            {(field) => (
              <field.TextField
                autoComplete="username"
                label="Username"
                placeholder="Enter Your Username"
              />
            )}
          </form.AppField>
          <form.AppField name="password">
            {(field) => (
              <field.PasswordField
                action={
                  <AuthLink href={forgotPasswordHref}>
                    Forgot Password?
                  </AuthLink>
                }
                autoComplete="current-password"
                label="Password"
                placeholder="Enter Your Password"
              />
            )}
          </form.AppField>
          <AuthSubmit pending={pending}>
            {pending ? "Signing In..." : "Sign In"}
          </AuthSubmit>
        </AuthForm>
      </CardContent>
    </>
  )
}

"use client"

import { useState } from "react"

import { CardContent, CardDescription } from "@/components/ui/card"
import {
  AuthButtonLink,
  AuthHeader,
  AuthPage,
  AuthTitle,
} from "@/components/openlmis/auth-card"
import {
  type SignInCredentials,
  SignInForm,
} from "@/components/openlmis/sign-in-page/sign-in-form"

// Mock account; swap the check for your own sign-in call.
const MOCK_USER = { username: "administrator", password: "password1" }

// oxlint-disable-next-line next/no-img-element -- items are framework-neutral
const logo = <img alt="OpenLMIS" src="https://registry.soldevelo.com/projects/openlmis.png" />

export function SignInPage() {
  const [error, setError] = useState<string>()
  const [signedIn, setSignedIn] = useState<string>()

  const signIn = ({ username, password }: SignInCredentials) => {
    if (username === MOCK_USER.username && password === MOCK_USER.password) {
      setError(undefined)
      setSignedIn(username)
    } else {
      setError("Check your username and password, then try again.")
    }
  }

  return (
    <AuthPage>
      {signedIn ? (
        <>
          <AuthHeader logo={logo}>
            <AuthTitle focus>Signed In</AuthTitle>
            <CardDescription>Welcome back, {signedIn}.</CardDescription>
          </AuthHeader>
          <CardContent>
            <AuthButtonLink href="/">Continue</AuthButtonLink>
          </CardContent>
        </>
      ) : (
        <SignInForm error={error} logo={logo} onSubmit={signIn} />
      )}
    </AuthPage>
  )
}

import { SignInPage } from "@/components/openlmis/sign-in-page/sign-in-page"

// A Next.js App Router route; in any other React app, render SignInPage from your own route.
export default function Page() {
  return <SignInPage />
}
